import * as React from "react";
import { cn } from "cn";
import { Select as SelectPrimitive } from "radix-ui";

import { useV4PortalContainer } from "../scope";

import { useFieldControlAttributes } from "../lib/field-context";
import { Icon } from "./icon";

import controlStyles from "./controls.module.css";
import menu from "./menu.module.css";

export type SelectOption = {
  value: string;
  label: string;
  description?: string;
  disabled?: boolean;
  group?: string;
};
function Select({
  options,
  label,
  placeholder = "Choose an option",
  size,
  invalid,
  align = "start",
  menuWidth,
  onChange,
  onValueChange,
  children,
  id,
  "aria-describedby": describedBy,
  ...props
}: React.ComponentProps<typeof SelectPrimitive.Root> & {
  options?: readonly SelectOption[];
  label?: string;
  placeholder?: string;
  size?: "sm" | "default" | "md" | "lg";
  invalid?: boolean;
  align?: "start" | "center" | "end";
  menuWidth?: React.CSSProperties["width"];
  onChange?: (value: string) => void;
  id?: string;
  "aria-describedby"?: string;
}) {
  const groups = [...new Set(options?.map((option) => option.group ?? ""))];
  return (
    <SelectPrimitive.Root
      data-slot="select"
      onValueChange={(value) => {
        onValueChange?.(value);
        onChange?.(value);
      }}
      {...props}
    >
      {options ? (
        <>
          <SelectTrigger
            id={id}
            size={size ?? "default"}
            aria-label={label}
            aria-describedby={describedBy}
            aria-invalid={invalid || undefined}
          >
            <SelectValue placeholder={placeholder} />
          </SelectTrigger>
          <SelectContent align={align} style={{ width: menuWidth }}>
            {groups.map((group) => (
              <SelectGroup key={group}>
                {group && <SelectLabel>{group}</SelectLabel>}
                {options
                  .filter((option) => (option.group ?? "") === group)
                  .map((option) => (
                    <SelectItem
                      key={option.value}
                      value={option.value}
                      disabled={option.disabled}
                      description={option.description}
                    >
                      <span data-slot="select-option-label">{option.label}</span>
                    </SelectItem>
                  ))}
              </SelectGroup>
            ))}
          </SelectContent>
        </>
      ) : (
        children
      )}
    </SelectPrimitive.Root>
  );
}

const SelectGroup = React.forwardRef<
  React.ComponentRef<typeof SelectPrimitive.Group>,
  React.ComponentPropsWithoutRef<typeof SelectPrimitive.Group>
>(({ className, ...props }, ref) => {
  return (
    <SelectPrimitive.Group ref={ref} data-slot="select-group" className={className} {...props} />
  );
});
SelectGroup.displayName = "SelectGroup";

const SelectValue = React.forwardRef<
  React.ComponentRef<typeof SelectPrimitive.Value>,
  React.ComponentPropsWithoutRef<typeof SelectPrimitive.Value>
>(({ ...props }, ref) => {
  return <SelectPrimitive.Value ref={ref} data-slot="select-value" {...props} />;
});
SelectValue.displayName = "SelectValue";

const SelectTrigger = React.forwardRef<
  React.ElementRef<typeof SelectPrimitive.Trigger>,
  React.ComponentPropsWithoutRef<typeof SelectPrimitive.Trigger> & {
    size?: "sm" | "default" | "md" | "lg";
  }
>(({ className, size = "default", children, ...props }, ref) => {
  const fieldAttributes = useFieldControlAttributes(props);
  return (
    <SelectPrimitive.Trigger
      ref={ref}
      data-slot="select-trigger"
      data-size={size}
      className={cn(
        controlStyles.field,
        controlStyles.trigger,
        controlStyles.insetHover,
        "[&_svg]:pointer-events-none [&_svg]:shrink-0",
        controlStyles.selectTrigger,
        className
      )}
      {...props}
      {...fieldAttributes}
    >
      {children}
      <SelectPrimitive.Icon asChild>
        <Icon name="chev-down" className={controlStyles.chevron} />
      </SelectPrimitive.Icon>
    </SelectPrimitive.Trigger>
  );
});
SelectTrigger.displayName = "SelectTrigger";

const SelectContent = React.forwardRef<
  React.ComponentRef<typeof SelectPrimitive.Content>,
  Omit<React.ComponentPropsWithoutRef<typeof SelectPrimitive.Content>, "position">
>(
  (
    { className, collisionPadding = 8, children, align = "start", sideOffset = 4, ...props },
    ref
  ) => {
    return (
      <SelectPrimitive.Portal container={useV4PortalContainer()}>
        <SelectPrimitive.Content
          ref={ref}
          data-slot="select-content"
          collisionPadding={collisionPadding}
          className={cn("relative z-50", menu.surface, menu.panel, menu.motion, className)}
          position="popper"
          align={align}
          sideOffset={sideOffset}
          {...props}
        >
          <SelectScrollUpButton />
          <SelectPrimitive.Viewport className={menu.inset}>{children}</SelectPrimitive.Viewport>
          <SelectScrollDownButton />
        </SelectPrimitive.Content>
      </SelectPrimitive.Portal>
    );
  }
);
SelectContent.displayName = "SelectContent";

const SelectLabel = React.forwardRef<
  React.ComponentRef<typeof SelectPrimitive.Label>,
  React.ComponentPropsWithoutRef<typeof SelectPrimitive.Label>
>(({ className, ...props }, ref) => {
  return (
    <SelectPrimitive.Label
      ref={ref}
      data-slot="select-label"
      className={cn(menu.label, className)}
      {...props}
    />
  );
});
SelectLabel.displayName = "SelectLabel";

const SelectItem = React.forwardRef<
  React.ComponentRef<typeof SelectPrimitive.Item>,
  React.ComponentPropsWithoutRef<typeof SelectPrimitive.Item> & { description?: string }
>(({ className, children, description, "aria-describedby": describedBy, ...props }, ref) => {
  const descriptionId = React.useId();
  return (
    <SelectPrimitive.Item
      ref={ref}
      data-slot="select-item"
      aria-describedby={
        [describedBy, description ? descriptionId : undefined].filter(Boolean).join(" ") ||
        undefined
      }
      className={cn(menu.row, className)}
      {...props}
    >
      <span className={menu.indicator}>
        <SelectPrimitive.ItemIndicator>
          <Icon name="check" />
        </SelectPrimitive.ItemIndicator>
      </span>
      <span className={menu.text}>
        <SelectPrimitive.ItemText className={menu.title}>{children}</SelectPrimitive.ItemText>
        {description && (
          <span id={descriptionId} className={menu.description}>
            {description}
          </span>
        )}
      </span>
    </SelectPrimitive.Item>
  );
});
SelectItem.displayName = "SelectItem";

const SelectSeparator = React.forwardRef<
  React.ComponentRef<typeof SelectPrimitive.Separator>,
  React.ComponentPropsWithoutRef<typeof SelectPrimitive.Separator>
>(({ className, ...props }, ref) => {
  return (
    <SelectPrimitive.Separator
      ref={ref}
      data-slot="select-separator"
      className={cn(menu.separator, className)}
      {...props}
    />
  );
});
SelectSeparator.displayName = "SelectSeparator";

const SelectScrollUpButton = React.forwardRef<
  React.ComponentRef<typeof SelectPrimitive.ScrollUpButton>,
  React.ComponentPropsWithoutRef<typeof SelectPrimitive.ScrollUpButton>
>(({ className, ...props }, ref) => {
  return (
    <SelectPrimitive.ScrollUpButton
      ref={ref}
      data-slot="select-scroll-up-button"
      className={cn(
        "z-10 flex cursor-default items-center justify-center bg-popover py-1 [&_svg:not([class*='size-'])]:size-4",
        className
      )}
      {...props}
    >
      <Icon name="chev-down" className="rotate-180" />
    </SelectPrimitive.ScrollUpButton>
  );
});
SelectScrollUpButton.displayName = "SelectScrollUpButton";

const SelectScrollDownButton = React.forwardRef<
  React.ComponentRef<typeof SelectPrimitive.ScrollDownButton>,
  React.ComponentPropsWithoutRef<typeof SelectPrimitive.ScrollDownButton>
>(({ className, ...props }, ref) => {
  return (
    <SelectPrimitive.ScrollDownButton
      ref={ref}
      data-slot="select-scroll-down-button"
      className={cn(
        "z-10 flex cursor-default items-center justify-center bg-popover py-1 [&_svg:not([class*='size-'])]:size-4",
        className
      )}
      {...props}
    >
      <Icon name="chev-down" />
    </SelectPrimitive.ScrollDownButton>
  );
});
SelectScrollDownButton.displayName = "SelectScrollDownButton";

export {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectLabel,
  SelectScrollDownButton,
  SelectScrollUpButton,
  SelectSeparator,
  SelectTrigger,
  SelectValue
};

.field {
  --v4-field-height: var(--v4-size-control-sm);
  --v4-field-inline: var(--v4-space-control-inline-sm);
  --v4-field-nested: var(--v4-size-nested-sm);
  box-sizing: border-box;
  min-height: var(--v4-field-height);
  padding-block: calc(
    (var(--v4-field-height) - var(--v4-type-body-line-height)) / 2 - var(--v4-size-control-border)
  );
  padding-inline: var(--v4-field-inline);
  border: var(--v4-size-control-border) solid var(--v4-control);
  border-radius: calc(var(--v4-radius-control) * var(--corners));
  background-color: var(--v4-control-surface);
  color: var(--v4-ink);
  font-family: var(--v4-type-body-font-family);
  font-size: var(--v4-type-body-font-size);
  line-height: var(--v4-type-body-line-height);
  font-weight: var(--v4-type-body-font-weight);
  letter-spacing: var(--v4-type-body-letter-spacing);
  outline: none;
  transition-property: border-color, box-shadow, background-color;
  transition-duration: var(--v4-duration-fast);
  transition-timing-function: var(--v4-ease-fade);
}
.field[data-size="md"] {
  --v4-field-height: var(--v4-size-control-md);
  --v4-field-inline: var(--v4-space-control-inline-md);
  --v4-field-nested: var(--v4-size-nested-md);
}
.field[data-size="lg"] {
  --v4-field-height: var(--v4-size-control-lg);
  --v4-field-inline: var(--v4-space-control-inline);
  --v4-field-nested: var(--v4-size-nested-lg);
}
.field::placeholder,
.field ::placeholder {
  color: var(--v4-muted);
}
@media (hover: hover) {
  .field:hover:not(:disabled, [aria-disabled="true"]) {
    background-color: var(--v4-control-surface-hover);
  }
}
.field:is(:focus-visible, [aria-expanded="true"]),
.field:has([data-field-control]:focus-visible, .field:is(:focus-visible, [aria-expanded="true"])) {
  border-color: var(--v4-ink);
  box-shadow: 0 0 0 var(--v4-size-focus-ring) var(--v4-focus-ring);
}
.field:is([aria-invalid="true"], [data-invalid]),
.field:has(:is([data-field-control], .field)[aria-invalid="true"]) {
  border-color: var(--v4-control-invalid-border);
}
.field:is([aria-invalid="true"], [data-invalid]):is(:focus-visible, [aria-expanded="true"]),
.field:is([aria-invalid="true"], [data-invalid]):has([data-field-control]:focus-visible),
.field:has(
    [data-field-control][aria-invalid="true"]:focus-visible,
    .field[aria-invalid="true"]:is(:focus-visible, [aria-expanded="true"])
  ) {
  border-color: var(--v4-bad);
  box-shadow: 0 0 0 var(--v4-size-focus-ring) var(--v4-focus-ring-bad);
}
.field:is(:disabled, [aria-disabled="true"]),
.field:has([data-field-control]:disabled) {
  cursor: not-allowed;
  opacity: 0.5;
}
.field:is([readonly], :has([data-field-control][readonly])) {
  background-color: var(--v4-paper);
}
.fieldBox {
  display: flex;
  width: 100%;
  min-width: 0;
  align-items: center;
  gap: var(--v4-space-control-gap);
  padding-block: 0;
  cursor: text;
}
.fieldBox:has(> .trailing) {
  padding-inline-end: var(--v4-space-control-slot-inset);
}
.bare {
  flex: 1 1 auto;
  align-self: stretch;
  min-width: 0;
  min-height: calc(var(--v4-field-height) - 2 * var(--v4-size-control-border));
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  color: inherit;
  font: inherit;
  letter-spacing: inherit;
  outline: none;
}
.bare:disabled {
  cursor: not-allowed;
}
.mono {
  font-family: var(--v4-font-mono, monospace);
}
.leading,
.chevron {
  display: inline-flex;
  flex: none;
  color: var(--v4-muted);
  pointer-events: none;
}
.chevron {
  width: var(--v4-size-icon);
  height: var(--v4-size-icon);
}
.trigger {
  display: flex;
  width: 100%;
  align-items: center;
  justify-content: space-between;
  gap: var(--v4-space-control-gap);
  text-align: start;
  white-space: nowrap;
  cursor: pointer;
}
.insetHover {
  --v4-inset-hover-gap: calc(var(--v4-space-2) + var(--v4-size-control-border));
  --v4-inset-hover-rest: var(--v4-control-surface);
  background-repeat: no-repeat;
  background-position: center;
  background-size: calc(100% - 2 * var(--v4-inset-hover-gap))
    calc(100% - 2 * var(--v4-inset-hover-gap));
}
.insetHover:is([data-variant="outline"], [data-variant="secondary"]) {
  --v4-inset-hover-rest: var(--v4-action-outline-surface);
}
@media (hover: hover) {
  .insetHover:hover:not(:disabled, [aria-disabled="true"]) {
    background-color: var(--v4-inset-hover-rest);
    background-image: linear-gradient(var(--v4-action-ghost-hover), var(--v4-action-ghost-hover));
  }
}
.insetHover[aria-expanded="true"] {
  background-color: var(--v4-inset-hover-rest);
  background-image: linear-gradient(var(--v4-action-ghost-hover), var(--v4-action-ghost-hover));
}
.trigger > :first-child {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.trigger [data-placeholder],
.trigger[data-placeholder] > :first-child {
  color: var(--v4-muted);
}
.textarea {
  min-height: calc(2 * var(--v4-space-32));
  field-sizing: content;
  resize: vertical;
}
.searchRow {
  display: flex;
  min-height: var(--v4-size-control-lg);
  align-items: center;
  gap: var(--v4-space-8);
  padding-inline: calc(var(--v4-space-menu-inset) + var(--v4-space-8));
  border-bottom: var(--v4-size-control-border) solid var(--v4-line-soft);
  color: var(--v4-muted);
  cursor: text;
}
.searchRow:focus-within {
  color: var(--v4-ink);
}
.searchRow > svg {
  flex: none;
  pointer-events: none;
}
.searchRow > input {
  flex: 1 1 auto;
  align-self: stretch;
  min-width: 0;
  margin: 0;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--v4-ink);
  caret-color: var(--v4-ink);
  font-family: var(--v4-type-body-font-family);
  font-size: var(--v4-type-body-font-size);
  line-height: var(--v4-type-body-line-height);
  font-weight: var(--v4-type-body-font-weight);
  letter-spacing: var(--v4-type-body-letter-spacing);
  outline: none;
}
.searchRow > input::placeholder {
  color: var(--v4-muted);
}
.searchTrailing {
  display: inline-flex;
  flex: none;
  align-items: center;
  color: var(--v4-muted);
}
.searchRow > input:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}
.focusOutline:focus-visible,
.focusOutlineWithin:has(> :focus-visible) {
  outline: var(--v4-size-focus-ring) solid var(--v4-ink);
  outline-offset: var(--v4-size-focus-ring);
}
.focusOutlineInset:focus-visible {
  outline: var(--v4-size-focus-ring) solid var(--v4-ink);
  outline-offset: calc(-1 * var(--v4-size-focus-ring));
}
.selectTrigger {
  width: fit-content;
  max-width: 100%;
  min-width: 0;
}
.selectTrigger [data-slot="select-value"] {
  display: block;
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.group[data-variant="toolbar"] {
  gap: var(--v4-space-4);
}
.group[data-variant="spaced"] {
  gap: var(--v4-space-8);
  flex-wrap: wrap;
}
.group[data-variant="toolbar"] > *,
.group[data-variant="spaced"] > * {
  border-radius: calc(var(--v4-radius-control) * var(--corners));
}
.group[data-variant="toolbar"] > [data-slot="button"],
.group[data-variant="spaced"] > [data-slot="button"] {
  border-width: 1px;
}
.card {
  --v4-card-inset: var(--v4-space-surface-inset);
  --v4-card-body-inset: var(--v4-card-inset);
  --v4-card-lead: 0px;
  display: flex;
  flex-direction: column;
  gap: 0;
  min-width: 0;
  padding: 0;
  background: var(--v4-pop);
  border: var(--v4-size-control-border) solid var(--v4-line);
  border-radius: calc(var(--v4-radius-card) * var(--corners));
  box-shadow: none;
  font-family: var(--v4-type-body-font-family);
  font-size: var(--v4-type-body-font-size);
  line-height: var(--v4-type-body-line-height);
  font-weight: var(--v4-type-body-font-weight);
  letter-spacing: var(--v4-type-body-letter-spacing);
  container-type: inline-size;
}
.card[data-size="sm"] {
  --v4-card-inset: var(--v4-space-surface-inset-sm);
}
.card:has(> .cardHeader [data-slot="media"]) {
  --v4-card-lead: calc(var(--v4-size-control-lg) + var(--v4-space-12));
}
.card:has(> .cardHeader [data-slot="media"][data-size="sm"]) {
  --v4-card-lead: calc(var(--v4-size-icon) + var(--v4-space-12));
}
.cardHeader {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: start;
  gap: var(--v4-space-4) var(--v4-space-12);
  min-width: 0;
  padding: var(--v4-card-inset);
}
.cardHeading {
  min-width: 0;
  overflow-wrap: anywhere;
  font-family: var(--v4-type-title-sm-font-family);
  font-size: var(--v4-type-title-sm-font-size);
  line-height: var(--v4-type-title-sm-line-height);
  font-weight: var(--v4-type-title-sm-font-weight);
  letter-spacing: var(--v4-type-title-sm-letter-spacing);
}
.cardBody {
  min-width: 0;
  padding: var(--v4-card-body-inset);
  padding-inline-start: calc(var(--v4-card-body-inset) + var(--v4-card-lead));
}
.cardHeader + .cardBody {
  padding-top: 0;
}
.cardPlain {
  background: transparent;
}
.cardMedia {
  flex: 0 0 auto;
  display: inline-flex;
}
.cardTitleGroup {
  display: flex;
  align-items: flex-start;
  gap: var(--v4-space-12);
  min-width: 0;
  grid-column: 1;
  grid-row: 1 / span 2;
}
.cardCopy {
  flex: 1;
  min-width: 0;
}
.cardHeader > [data-slot="card-title"],
.cardHeader > [data-slot="card-description"] {
  grid-column: 1;
}
.cardDescription {
  color: var(--v4-text2);
  margin-top: var(--v4-space-4);
  overflow-wrap: anywhere;
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
}
.cardHeader > [data-slot="card-description"] {
  margin-top: 0;
}
.cardAction {
  display: flex;
  align-items: center;
  gap: var(--v4-space-8);
  max-width: 100%;
  height: var(--v4-type-title-sm-line-height);
  margin-inline-start: auto;
  grid-column: 2;
  grid-row: 1;
}
.cardFooter {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: var(--v4-space-12);
  min-width: 0;
  padding: var(--v4-space-12) var(--v4-card-inset);
  padding-inline-start: calc(var(--v4-card-inset) + var(--v4-card-lead));
  border-top: var(--v4-size-control-border) solid var(--v4-line);
  color: var(--v4-text2);
  overflow-wrap: anywhere;
}
.choice {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  cursor: pointer;
}
.choiceText {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.choiceTitle {
  font-family: var(--v4-type-field-label-font-family);
  font-size: var(--v4-type-field-label-font-size);
  line-height: var(--v4-type-field-label-line-height);
  font-weight: var(--v4-type-body-font-weight);
  letter-spacing: var(--v4-type-field-label-letter-spacing);
  color: var(--v4-ink);
}
.choiceDescription {
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
  color: var(--v4-muted);
}
.choiceRow {
  align-items: center;
  justify-content: space-between;
  padding-block: 12px;
  border-bottom: 1px solid var(--v4-line-soft);
}
.switch {
  --v4-switch-travel: 16px;
  box-sizing: border-box;
  border: var(--v4-size-control-border) solid transparent;
  background-color: var(--v4-switch-off-surface);
  transition-property: background-color;
  transition-duration: var(--v4-duration-fast);
  transition-timing-function: var(--v4-ease-standard);
}
.switch[data-size="default"] {
  width: 36px;
  height: 20px;
  padding: 2px;
}
.switch[data-size="sm"] {
  --v4-switch-travel: 12px;
  width: 28px;
  height: 16px;
  padding: 2px;
}
.switchThumb {
  width: 14px;
  height: 14px;
  background-color: var(--v4-switch-thumb);
  box-shadow:
    0 0 0 var(--v4-size-control-border) var(--v4-switch-thumb-line),
    0 1px 2px color-mix(in oklab, var(--v4-frame) 24%, transparent);
  transition-property: background-color, box-shadow;
  transition-duration: var(--v4-duration-fast);
  transition-timing-function: var(--v4-ease-fade);
}
.switch[data-size="sm"] > .switchThumb {
  width: 10px;
  height: 10px;
}
.switch[data-state="checked"] {
  background-color: var(--v4-sw-on);
}
.switch[data-state="checked"] > .switchThumb {
  background-color: var(--v4-sw-knob-on);
  box-shadow: 0 1px 2px color-mix(in oklab, var(--v4-frame) 24%, transparent);
